import {BUILDING_MATERIAL_LIMIT,encodePaintMaterial,decodePaintMaterial} from './building-paint-colors.js?v=architecture-collection-58';
import {BUILDING_MATERIALS,materialSurfaceColor,drawMaterialDetail} from './building-materials.js?v=architecture-collection-58';
import {projectBuildingPoint} from './building-footprints.js?v=architecture-collection-58';
export function validateGroundPaint(value){if(typeof value!=='string'||value.length!==100||/[^0-9a-z]/.test(value))throw Error('Ground paint needs 100 valid material entries.');return value;}
export function groundMaterial(design,index){return decodePaintMaterial(design.groundPaint?.[index]||'0');}
export function groundFaces(design,rotation=0){return Array.from({length:100},(_,index)=>{const x=index%10,y=Math.floor(index/10),a=x/10-.5,b=y/10-.5,points=[[a,b,0],[a+.1,b,0],[a+.1,b+.1,0],[a,b+.1,0]];return{index,x,y,side:4,from:0,to:1,points,polygon:points.map(p=>projectBuildingPoint(p,rotation,design.footprint))};});}
export function groundCovered(design,index){if(!design.blocks&&!design.voxels){const x=(index%10+.5)/10-.5,y=(Math.floor(index/10)+.5)/10-.5;return Math.abs(x)<=(design.width*.085+.08)/2&&Math.abs(y)<=(design.depth*.085+.08)/2;}const x=Math.floor(((index%10+.5)/10-.5)/.085+5),y=Math.floor(((Math.floor(index/10)+.5)/10-.5)/.085+5);if(x<0||x>=10||y<0||y>=10)return false;const cell=y*10+x;return Boolean(design.blocks?.[cell]||((design.voxels?.[cell]||0)&1));}
export function paintGround(design,indices,material){if(!Number.isInteger(material)||material< -1||material>=BUILDING_MATERIAL_LIMIT||material>=7&&!design.paintColors?.[material-7])throw Error('Choose a ground material.');const next=(design.groundPaint?validateGroundPaint(design.groundPaint):'0'.repeat(100)).split('');for(const i of indices){if(!Number.isInteger(i)||i<0||i>=100)throw Error('Choose a ground square.');next[i]=material===-1?'0':encodePaintMaterial(material);}return next.join('');}
export function connectedGround(design,start){if(!Number.isInteger(start)||start<0||start>=100||groundCovered(design,start))return[];const original=groundMaterial(design,start),result=[],seen=new Set(),queue=[start];while(queue.length){const i=queue.pop();if(seen.has(i))continue;seen.add(i);if(groundCovered(design,i)||groundMaterial(design,i)!==original)continue;result.push(i);const x=i%10,y=Math.floor(i/10);if(x)queue.push(i-1);if(x<9)queue.push(i+1);if(y)queue.push(i-10);if(y<9)queue.push(i+10);}return result;}
export function drawGroundPaint(design,polygon){if(!design.groundPaint)return;for(const face of groundFaces(design)){const material=groundMaterial(design,face.index);if(material<0)continue;polygon(face.points,materialSurfaceColor(material,design));drawMaterialDetail(face,material,design,polygon);}}
